/// SVG for a derived [`Liveness`] state.
pub fn status_svg(l: Liveness) -> &'static str {
    match l {
        Liveness::Live => CIRCLE_CHECK,
        Liveness::Stale => TRIANGLE_ALERT,
        Liveness::Down => CIRCLE_X,
        Liveness::AwaitingFirstHeartbeat => CIRCLE_DASHED,
    }
}
